from pathlib import Path
import re
pattern=r'(None|LoRA|GPTQ|OmniQ|LoftQ\\*|QLoRA\\*|QA-LoRA|QAT-LoRA|L4Q)\\s+([0-9&]+)\\s+(.*)'
rows=[]
for p in [23,24]:
 model=''
 for line in Path(f'tmp/pdfs/page-{p}-layout.txt').read_text().splitlines():
  m=re.search(pattern,line)
  if not m: continue
  if line[:m.start()].strip(): model=line[:m.start()].strip()
  vals=[float(x) for x in re.findall(r'\\d+\\.\\d+',m[3])]
  if len(vals)"'!=10: continue
  for shot,start in [(0,0),(5,5)]:
   v=vals[start:start+5]
   rows.append((p,model,m[1],m[2],shot,v[:4],v[4]))
def fit(rows):
 a=[[0.0]*4 for _ in range(3)]
 for *_,v,y in rows:
  x=[v[j]-v[3] for j in range(3)]
  for i in range(3):
   for j in range(3): a[i][j]+=x[i]*x[j]
   a[i][3]+=x[i]*(y-v[3])
 for i in range(3):
  k=max(range(i,3),key=lambda k:abs(a[k][i]))
  a[i],a[k]=a[k],a[i]
  z=a[i][i]; a[i]=[x/z for x in a[i]]
  for k in range(3):
   if k!=i:
    z=a[k][i];a[k]=[a[k][j]-z*a[i][j] for j in range(4)]
 w=[a[i][3] for i in range(3)]
 return w+[1-sum(w)]
def pred(w,r): return sum(x*y for x,y in zip(w,r[-2]))
kept=rows
for i in range(4):
 w=fit(kept)
 kept=[r for r in rows if abs(pred(w,r)-r[-1])<.15]
print('"'Rows',len(rows),'fitted weights',w,'retained',len(kept))
for r in rows:
 if abs(pred(w,r)-r[-1])>.2:
  print('Aggregation discrepancy',r,'weighted aggregate',round(pred(w,r),2))
